import*as a from"../common/ops/hyperbolic.js";import*as t from"../common/ops/trig.js";import{fromStorage as e,toStorage as o}from"./types.js";function i(r){return e(t.sin(o(r)))}function f(r){return e(t.cos(o(r)))}function x(r){return e(t.tan(o(r)))}function y(r){return e(t.arcsin(o(r)))}const h=y;function u(r){return e(t.arccos(o(r)))}const d=u;function A(r){return e(t.arctan(o(r)))}const g=A;function C(r,n){const c=typeof n=="number"?n:o(n);return e(t.arctan2(o(r),c))}const m=C;function b(r,n){const c=typeof n=="number"?n:o(n);return e(t.hypot(o(r),c))}function S(r){return e(t.degrees(o(r)))}function O(r){return e(t.radians(o(r)))}function l(r){return e(t.deg2rad(o(r)))}function j(r){return e(t.rad2deg(o(r)))}function k(r){return e(a.sinh(o(r)))}function q(r){return e(a.cosh(o(r)))}function v(r){return e(a.tanh(o(r)))}function D(r){return e(a.arcsinh(o(r)))}const w=D;function N(r){return e(a.arccosh(o(r)))}const z=N;function s(r){return e(a.arctanh(o(r)))}const B=s;export{d as acos,z as acosh,u as arccos,N as arccosh,y as arcsin,D as arcsinh,A as arctan,C as arctan2,s as arctanh,h as asin,w as asinh,g as atan,m as atan2,B as atanh,f as cos,q as cosh,l as deg2rad,S as degrees,b as hypot,j as rad2deg,O as radians,i as sin,k as sinh,x as tan,v as tanh};
